# Shared item-card data must outlive the character which supplied it.
_DOPPEL_CARD_LISTS = (
    "GD_AttributePresentation._AttributeList.DefaultPresentationList",
    "GD_AttributePresentation._AttributeList.ClassModOverridePresentationList",
)
_doppel_card_refs = {}
_doppel_card_reader = None


def _doppel_card_read(address, size):
    """Checked copy of pointer values; never wrap a borrowed native entry."""
    global _doppel_card_reader
    import ctypes
    if not address or size <= 0:
        return None
    if _doppel_card_reader is None:
        kernel = ctypes.WinDLL("kernel32", use_last_error=True)
        kernel.GetCurrentProcess.argtypes = []
        kernel.GetCurrentProcess.restype = ctypes.c_void_p
        read = kernel.ReadProcessMemory
        read.argtypes = [ctypes.c_void_p, ctypes.c_void_p, ctypes.c_void_p,
                         ctypes.c_size_t, ctypes.POINTER(ctypes.c_size_t)]
        read.restype = ctypes.c_int
        _doppel_card_reader = read, kernel.GetCurrentProcess()
    read, process = _doppel_card_reader
    buffer = ctypes.create_string_buffer(size)
    copied = ctypes.c_size_t()
    if not read(process, address, buffer, size, ctypes.byref(copied)):
        return None
    return buffer.raw if copied.value == size else None


def _doppel_card_addresses(array):
    import ctypes
    import struct
    if ctypes.sizeof(ctypes.c_void_p) != 4 or array._type.ElementSize != 4:
        return None
    address = array._get_address()
    header = _doppel_card_read(address, 12)
    if header is None:
        return None
    data, count, capacity = struct.unpack("<Iii", header)
    if not 0 <= count <= capacity <= 4096 or count != len(array):
        return None
    body = _doppel_card_read(data, count * 4) if count else b""
    if body is None or _doppel_card_read(address, 12) != header:
        return None
    return struct.unpack(f"<{count}I", body)


def _doppel_card_protect(reason):
    """Protect both shared lists before the first save/map load, without a pawn.

    The 2026-09-21 dump faults at native presentation lookup index 338;
    that is the first third-party Jack entry in the restarted game's list.
    Gameplay COM maintenance happens too late for a new Jack (TPS).
    Only package data is rooted. No loads, pawn reads or native raw writes.
    """
    if _teardown[0] or _stream.get("muted"):
        return False
    dead_flags = 0x18000 | (0x20000002 << 32)
    try:
        batches = []
        wanted = set()
        for path in _DOPPEL_CARD_LISTS:
            registry = _find(path)
            if registry is None or int(registry.ObjectFlags) & dead_flags:
                continue
            array = registry.Attributes
            addresses = _doppel_card_addresses(array)
            if addresses is None:
                _report([f"[doppel-card] {reason}: pointer snapshot unavailable"])
                return False
            batches.append((registry, array, addresses))
            wanted.update(addresses)
        wanted.discard(0)
        live = {}
        for address in wanted:
            ref = _doppel_card_refs.get(address)
            obj = ref() if ref is not None else None
            if (obj is not None and obj._get_address() == address
                    and not int(obj.ObjectFlags) & dead_flags):
                live[address] = obj
        missing = wanted - live.keys()
        if missing:
            for obj in unrealsdk.find_all("AttributePresentationDefinition", exact=False):
                address = obj._get_address()
                if address in missing and not int(obj.ObjectFlags) & dead_flags:
                    live[address] = obj
                    _doppel_card_refs[address] = unrealsdk.unreal.WeakPointer(obj)
        # Validate all snapshots before changing either shared list.
        if any(_doppel_card_addresses(array) != addresses
               for _, array, addresses in batches):
            _report([f"[doppel-card] {reason}: shared list changed; deferred"])
            return False
        for obj in live.values():
            obj.ObjectFlags |= KEEP_FLAG
        removed = 0
        for registry, array, addresses in batches:
            registry.ObjectFlags |= KEEP_FLAG
            invalid = sum(bool(a and a not in live) for a in addresses)
            if invalid:
                registry.Attributes = [live.get(a) for a in addresses]
                removed += invalid
        for address in tuple(_doppel_card_refs):
            if address not in live:
                _doppel_card_refs.pop(address, None)
        if batches:
            _report([f"[doppel-card] {reason}: protected {len(live)} shared labels "
                     f"in {len(batches)} lists; cleared {removed} invalid references"])
        return bool(batches)
    except Exception as exc:
        _report([f"[doppel-card] {reason}: protection deferred: {type(exc).__name__}"])
        return False


@hook("WillowGame.WillowGameViewportClient:NotifyDlcRefreshComplete", Type.POST_UNCONDITIONAL)
def _doppel_card_after_dlc(obj, args, ret, func):
    # The other mod appends its labels in PRE. Protect them before the
    # frontend's later save load or a non-Jack pawn releases its referencer.
    _doppel_card_protect("DLC refresh")

# Doppelganger ships its own copy of Quince_Doppel_Skills.SkillTree.Branch_Actionskill_Doppelganger, the
# root of our Jack's tree, with its Skill_DeathTrap in the action slot. Whichever package loads first owns
# that path, so our Jack's action skill could become his and a loaded save's action point was dropped.
_DOPPEL_TREE = "Quince_Doppel_Streaming.SkillTree.SkillTree_Doppelganger"
_DOPPEL_ACTION = "Quince_Doppel_Skills.ActionSkill.Skill_SummonDigiJack"
_FOREIGN_ACTION = "GD_Doppelganger_Skills.Action.Skill_DeathTrap"
_DOPPEL_OWN_ROOT = "Branch_Actionskill_MoonshotJack"


def _doppel_own_root(lines):
    """Give our Jack's tree a root branch nobody else ships.  -> 1 when the tree was changed."""
    try:
        tree = _find(_DOPPEL_TREE)
        action = _find(_DOPPEL_ACTION)
        root = tree.Root if tree is not None else None
        if root is None or action is None:
            return 0
        own = root if str(root.Name) == _DOPPEL_OWN_ROOT else _cryo_mk(
            "SkillTreeBranchDefinition", tree, _DOPPEL_OWN_ROOT, template=root)
        if own is None:
            return 0
        changed = 0
        tiers = own.Tiers
        if len(tiers) and len(tiers[0].Skills):
            tier = tiers[0]
            if str(tier.Skills[0]) != str(action):
                tier.Skills[0] = action
                tiers[0] = tier                # nested struct arrays: write the element back
                changed = 1
        if str(tree.Root) != str(own):
            tree.Root = own
            changed = 1
        _keep_obj(own)
        if changed and lines is not None:
            lines.append("[doppel] tree root is our own " + _DOPPEL_OWN_ROOT
                         + " (action skill Skill_SummonDigiJack), not the other mod's copy")
        return changed
    except Exception as exc:
        if lines is not None:
            lines.append(f"[doppel] own tree root failed: {exc!r}")
        return 0


def _doppel_skill_alias(path, pc):
    """Our Jack's action-skill grade belongs on whichever root his live tree was built with."""
    if path not in (_DOPPEL_ACTION, _FOREIGN_ACTION):
        return path
    try:
        if _our_class(str(pc.PlayerClass)) != "doppel":
            return path
        live = pc.PlayerSkillTree.GetActionSkill()
        live_path = _gun_safety_path(live) if live is not None else ""
        if live_path in (_DOPPEL_ACTION, _FOREIGN_ACTION):
            return live_path
    except Exception:
        pass
    return path

