_GUN_SAFETY_OWNER = {"id": 0, "at": 0.0, "owner": {}}
_GUN_SAFETY_FOREIGN_SAID = set()


def _gun_safety_owner(pc):
    """The live character behind the gun backup: its SaveGuid and class.

    Backups are filed by save-slot number, and BL2 gives a deleted
    character's number to the next new one. The owner stamp is what tells
    the two characters apart (doppel-compat r11).
    """
    if pc is None:
        return {}
    save_id = _campaign_save_id(pc)
    now = time.monotonic()
    if (save_id and _GUN_SAFETY_OWNER["id"] == save_id
            and now - _GUN_SAFETY_OWNER["at"] < 5.0):
        return _GUN_SAFETY_OWNER["owner"]
    owner = {}
    try:
        sg = pc.GetCachedSaveGame()
    except Exception:
        sg = None
    try:
        guid = sg.SaveGuid
        parts = tuple(int(getattr(guid, n, 0) or 0) & 0xFFFFFFFF
                      for n in ("A", "B", "C", "D"))
        if any(parts):
            owner["guid"] = "%08x-%08x-%08x-%08x" % parts
    except Exception:
        pass
    cls = None
    try:
        cls = sg.PlayerClassDefinition
    except Exception:
        cls = None
    if cls is None:
        try:
            cls = pc.PlayerClass
        except Exception:
            cls = None
    if cls is not None:
        owner["class"] = str(cls)
    if save_id:
        _GUN_SAFETY_OWNER.update(id=save_id, at=now, owner=owner)
    return owner


def _gun_safety_owner_mismatch(record, owner):
    """Why *record* belongs to another character, or "" if it may be used.

    A record without a stamp (written before r11) cannot be checked here;
    _gun_safety_orphan_sweep retires those once their save file is gone.
    """
    stamp = record.get("owner") if isinstance(record, dict) else None
    if not isinstance(stamp, dict) or not owner:
        return ""
    if stamp.get("guid") and owner.get("guid"):
        if stamp["guid"] != owner["guid"]:
            return f"SaveGuid {stamp['guid']}, live {owner['guid']}"
        return ""
    try:
        switching = bool((_hunter_switch.state or {}).get("on"))
    except Exception:
        switching = False
    if (not switching and stamp.get("class") and owner.get("class")
            and stamp["class"] != owner["class"]):
        return f"class {stamp['class']}, live {owner['class']}"
    return ""


def _gun_safety_foreign(save_id, record, pc=None):
    """Non-empty when this save's backup was written for another character."""
    try:
        if pc is None:
            pc = get_pc()
    except Exception:
        pc = None
    why = _gun_safety_owner_mismatch(record, _gun_safety_owner(pc))
    if why and (save_id, why) not in _GUN_SAFETY_FOREIGN_SAID:
        _GUN_SAFETY_FOREIGN_SAID.add((save_id, why))
        _report([f"[gun-safety] save {save_id}: the backup under this slot "
                 f"belongs to another character ({why}); not restored"])
    return why


def _gun_safety_orphan_park(data, key, record, why):
    """Keep a retired backup under "orphaned" instead of deleting it."""
    stamp = time.strftime("%Y%m%dT%H%M%S")
    parked = data.setdefault("orphaned", {})
    parked[f"{key}@{stamp}"] = {"why": why, "record": record}


def _gun_safety_orphan_sweep(pc=None):
    """Retire backups whose save file is gone, before New Game reuses the slot.

    Runs on LaunchNewGame, the only point where BL2 hands out a save id.
    The gun records move under "orphaned" in moonshot_tps_guns.json and the
    per-save sidecars move to moonshot_saves/orphaned/; nothing is deleted.
    """
    try:
        roots = [p for p in _campaign_save_data_roots() if p.exists()]
    except Exception:
        roots = []
    if not roots:
        return 0
    # The .sav files are the truth: the menu's save list can still name a
    # character deleted a moment ago. It is only the fallback when the scan
    # finds no file at all (a save folder this scan does not know).
    live = set(_save_io.save_ids_on_disk(roots))
    if not live:
        try:
            live = set(_campaign_existing_save_ids(pc))
        except Exception:
            live = set()
    parked = []
    data = _gun_safety_read()
    if not _gun_safety.get("unreadable"):
        saves = data.get("saves") or {}
        for key in list(saves):
            try:
                if int(key) in live:
                    continue
            except Exception:
                continue
            _gun_safety_orphan_park(data, key, saves.pop(key),
                                    "save file deleted")
            parked.append(key)
        if parked:
            _atomic_json_write(TPS_GUN_FILE, data)
            _gun_safety["cache"] = data
    moved = []
    try:
        stamp = time.strftime("%Y%m%dT%H%M%S")
        for side in sorted(MOONSHOT_SAVE_DIR.glob("Save*.json")):
            match = re.fullmatch(r"Save([0-9A-Fa-f]{4})\..+\.json", side.name)
            if not match or int(match.group(1), 16) in live:
                continue
            dest = MOONSHOT_SAVE_DIR / "orphaned" / f"{stamp}-{side.name}"
            dest.parent.mkdir(exist_ok=True)
            os.replace(str(side), str(dest))
            moved.append(side.name)
    except Exception as exc:
        _report([f"[gun-safety] orphan sweep: sidecar move failed: {exc!r}"])
    if parked or moved:
        _report([f"[gun-safety] orphan sweep: {len(parked)} gun backup(s) "
                 f"({', '.join(parked) or 'none'}) and {len(moved)} "
                 f"sidecar(s) belonged to deleted saves and were retired"]
                + ["  " + name for name in moved])
    return len(parked) + len(moved)

